const chai = require('chai'),
  expect = chai.expect,
  Support = require('../../support'),
  dialect = Support.getTestDialect(),
  config = require('../../../config/config'),
  DataTypes = require('../../../../lib/data-types');

if (dialect.match(/^postgres/)) {
  describe('[POSTGRES Specific] associations', () => {
    describe('many-to-many', () => {
      describe('where tables have the same prefix', () => {
        it('should create a table wp_table1wp_table2s', function() {
          const Table2 = this.sequelize.define('wp_table2', { foo: DataTypes.STRING }),
            Table1 = this.sequelize.define('wp_table1', { foo: DataTypes.STRING });

          Table1.belongsToMany(Table2, { through: 'wp_table1swp_table2s' });
          Table2.belongsToMany(Table1, { through: 'wp_table1swp_table2s' });

          expect(this.sequelize.modelManager.getModel('wp_table1swp_table2s')).to.exist;
        });
      });

      describe('when join table name is specified', () => {
        beforeEach(function() {
          const Table2 = this.sequelize.define('ms_table1', { foo: DataTypes.STRING }),
            Table1 = this.sequelize.define('ms_table2', { foo: DataTypes.STRING });

          Table1.belongsToMany(Table2, { through: 'table1_to_table2' });
          Table2.belongsToMany(Table1, { through: 'table1_to_table2' });
        });

        it('should not use a combined name', function() {
          expect(this.sequelize.modelManager.getModel('ms_table1sms_table2s')).not.to.exist;
        });

        it('should use the specified name', function() {
          expect(this.sequelize.modelManager.getModel('table1_to_table2')).to.exist;
        });
      });
    });

    describe('HasMany', () => {
      describe('addDAO / getModel', () => {
        beforeEach(function() {
          //prevent periods from occurring in the table name since they are used to delimit (table.column)
          this.User = this.sequelize.define(`User${config.rand()}`, { name: DataTypes.STRING });
          this.Task = this.sequelize.define(`Task${config.rand()}`, { name: DataTypes.STRING });
          this.users = null;
          this.tasks = null;

          this.User.belongsToMany(this.Task, { as: 'Tasks', through: 'usertasks' });
          this.Task.belongsToMany(this.User, { as: 'Users', through: 'usertasks' });

          const users = [],
            tasks = [];

          for (let i = 0; i < 5; ++i) {
            users[i] = { name: `User${Math.random()}` };
            tasks[i] = { name: `Task${Math.random()}` };
          }

          return this.sequelize.sync({ force: true }).then(() => {
            return this.User.bulkCreate(users).then(() => {
              return this.Task.bulkCreate(tasks).then(() => {
                return this.User.findAll().then(_users => {
                  return this.Task.findAll().then(_tasks => {
                    this.user = _users[0];
                    this.task = _tasks[0];
                  });
                });
              });
            });
          });
        });

        it('should correctly add an association to the dao', function() {
          return this.user.getTasks().then(_tasks => {
            expect(_tasks).to.have.length(0);
            return this.user.addTask(this.task).then(() => {
              return this.user.getTasks().then(_tasks => {
                expect(_tasks).to.have.length(1);
              });
            });
          });
        });
      });

      describe('removeDAO', () => {
        it('should correctly remove associated objects', function() {
          const users = [],
            tasks = [];

          //prevent periods from occurring in the table name since they are used to delimit (table.column)
          this.User = this.sequelize.define(`User${config.rand()}`, { name: DataTypes.STRING });
          this.Task = this.sequelize.define(`Task${config.rand()}`, { name: DataTypes.STRING });
          this.users = null;
          this.tasks = null;

          this.User.belongsToMany(this.Task, { as: 'Tasks', through: 'usertasks' });
          this.Task.belongsToMany(this.User, { as: 'Users', through: 'usertasks' });

          for (let i = 0; i < 5; ++i) {
            users[i] = { id: i + 1, name: `User${Math.random()}` };
            tasks[i] = { id: i + 1, name: `Task${Math.random()}` };
          }

          return this.sequelize.sync({ force: true }).then(() => {
            return this.User.bulkCreate(users).then(() => {
              return this.Task.bulkCreate(tasks).then(() => {
                return this.User.findAll().then(_users => {
                  return this.Task.findAll().then(_tasks => {
                    this.user = _users[0];
                    this.task = _tasks[0];
                    this.users = _users;
                    this.tasks = _tasks;

                    return this.user.getTasks().then(__tasks => {
                      expect(__tasks).to.have.length(0);
                      return this.user.setTasks(this.tasks).then(() => {
                        return this.user.getTasks().then(_tasks => {
                          expect(_tasks).to.have.length(this.tasks.length);
                          return this.user.removeTask(this.tasks[0]).then(() => {
                            return this.user.getTasks().then(_tasks => {
                              expect(_tasks).to.have.length(this.tasks.length - 1);
                              return this.user.removeTasks([this.tasks[1], this.tasks[2]]).then(() => {
                                return this.user.getTasks().then(_tasks => {
                                  expect(_tasks).to.have.length(this.tasks.length - 3);
                                });
                              });
                            });
                          });
                        });
                      });
                    });
                  });
                });
              });
            });
          });
        });
      });
    });
  });
}

'use strict';

const chai = require('chai'),
  expect = chai.expect,
  Support = require('./support'),
  Promise = require('../../lib/promise'),
  Transaction = require('../../lib/transaction'),
  sinon = require('sinon'),
  current = Support.sequelize;

if (current.dialect.supports.transactions) {

  describe(Support.getTestDialectTeaser('Sequelize#transaction'), () => {
    beforeEach(function() {
      this.sinon = sinon.createSandbox();
    });

    afterEach(function() {
      this.sinon.restore();
    });

    describe('then', () => {
      it('gets triggered once a transaction has been successfully committed', function() {
        let called = false;
        return this
          .sequelize
          .transaction().then(t => {
            return t.commit().then(() => {
              called = 1;
            });
          })
          .then(() => {
            expect(called).to.be.ok;
          });
      });

      it('gets triggered once a transaction has been successfully rolled back', function() {
        let called = false;
        return this
          .sequelize
          .transaction().then(t => {
            return t.rollback().then(() => {
              called = 1;
            });
          })
          .then(() => {
            expect(called).to.be.ok;
          });
      });

      if (Support.getTestDialect() !== 'sqlite') {
        it('works for long running transactions', function() {
          return Support.prepareTransactionTest(this.sequelize).then(sequelize => {
            this.sequelize = sequelize;

            this.User = sequelize.define('User', {
              name: Support.Sequelize.STRING
            }, { timestamps: false });

            return sequelize.sync({ force: true });
          }).then(() => {
            return this.sequelize.transaction();
          }).then(t => {
            let query = 'select sleep(2);';

            switch (Support.getTestDialect()) {
              case 'postgres':
                query = 'select pg_sleep(2);';
                break;
              case 'sqlite':
                query = 'select sqlite3_sleep(2000);';
                break;
              case 'mssql':
                query = 'WAITFOR DELAY \'00:00:02\';';
                break;
              default:
                break;
            }

            return this.sequelize.query(query, { transaction: t }).then(() => {
              return this.User.create({ name: 'foo' });
            }).then(() => {
              return this.sequelize.query(query, { transaction: t });
            }).then(() => {
              return t.commit();
            });
          }).then(() => {
            return this.User.findAll();
          }).then(users => {
            expect(users.length).to.equal(1);
            expect(users[0].name).to.equal('foo');
          });
        });
      }
    });

    describe('complex long running example', () => {
      it('works with promise syntax', function() {
        return Support.prepareTransactionTest(this.sequelize).then(sequelize => {
          const Test = sequelize.define('Test', {
            id: { type: Support.Sequelize.INTEGER, primaryKey: true, autoIncrement: true },
            name: { type: Support.Sequelize.STRING }
          });

          return sequelize.sync({ force: true }).then(() => {
            return sequelize.transaction().then(transaction => {
              expect(transaction).to.be.instanceOf(Transaction);

              return Test
                .create({ name: 'Peter' }, { transaction })
                .then(() => {
                  return Promise.delay(1000).then(() => {
                    return transaction
                      .commit()
                      .then(() => { return Test.count(); })
                      .then(count => {
                        expect(count).to.equal(1);
                      });
                  });
                });
            });
          });
        });
      });
    });

    describe('concurrency', () => {
      describe('having tables with uniqueness constraints', () => {
        beforeEach(function() {
          return Support.prepareTransactionTest(this.sequelize).then(sequelize => {
            this.sequelize = sequelize;

            this.Model = sequelize.define('Model', {
              name: { type: Support.Sequelize.STRING, unique: true }
            }, {
              timestamps: false
            });

            return this.Model.sync({ force: true });
          });
        });

        it('triggers the error event for the second transactions', function() {
          return this.sequelize.transaction().then(t1 => {
            return this.sequelize.transaction().then(t2 => {
              return this.Model.create({ name: 'omnom' }, { transaction: t1 }).then(() => {
                return Promise.all([
                  this.Model.create({ name: 'omnom' }, { transaction: t2 }).catch(err => {
                    expect(err).to.be.ok;
                    return t2.rollback();
                  }),
                  Promise.delay(100).then(() => {
                    return t1.commit();
                  })
                ]);
              });
            });
          });
        });
      });
    });
  });

}

import { Deferrable, Sequelize, Transaction } from 'sequelize';
import { User } from './models/User';

export const sequelize = new Sequelize('uri');

async function trans() {
    const a: number = await sequelize.transaction(async transaction => {
        transaction.afterCommit(() => console.log('transaction complete'));
        User.create(
            {
                data: 123,
            },
            {
                transaction,
            }
        );
        return 1;
    });
}

async function transact() {
    const t = await sequelize.transaction({
        deferrable: Deferrable.SET_DEFERRED(['test']),
        isolationLevel: Transaction.ISOLATION_LEVELS.READ_COMMITTED,
        type: Transaction.TYPES.DEFERRED,
    });
    await t.commit();
    await t.rollback();
}

transact();

